/// Provides one application's live access to an identity-wide Paykit runtime.
///
/// The provider is the boundary where the app or bindings expose current Pubky
/// access from platform storage and auth flows.
#[async_trait]
pub trait PubkySessionProvider: Send + Sync {
    /// Load live Pubky access for storage and Encrypted Link workflows.
    ///
    /// Returning `None` means no live session access is currently available. It
    /// does not sign the SDK out or clear identity-scoped storage; explicit
    /// sign-out is a separate runtime operation.
    async fn load_session_access(&self) -> Result<Option<PubkySessionAccess>>;

/// Authoritative logical state boundary for Paykit SDK.
///
/// Production adapters must provide atomic transactions with monotonic id
/// allocation, stable FIFO ordering for outbound/private-stream records, and
/// lease-aware writes. Apps sharing one Pubky identity must use the same
/// logical state backing. The SDK assumes all mutation methods called inside
/// one transaction either commit together or roll back together.
#[async_trait]
pub trait StorageAdapter: Send + Sync {

/// Encrypted identity-wide SDK state stored in Pubky.
///
/// All serving homeserver instances must run 0.16.2 or newer with GCS storage.
/// Server versions and backends are not checked automatically; the caller must
/// verify deployment independently of the client version and `webdav-locks`.
/// All participating state writers must use lock tokens, and pre-upgrade writes
/// must be drained before rollout. Direct backend edits are outside this contract.
/// Each operation reads the latest complete state under a renewed homeserver
/// write lock. Its transactions reuse that state and replace the encrypted
/// resource whenever it changes, before returning. One instance serializes its
/// own operations. State is never reused after releasing the homeserver lock.
/// Encryption protects state contents and integrity, but not resource
/// existence, size, update timing, or replay by the homeserver. Unconfirmed
/// writes leave a remote marker. Before using that state, the next operation
/// republishes its exact bytes under the renewed lock. The confirmed publication
/// fences older GCS generations, including writes whose SQL transaction died.
/// Cancellation or failed publication leaves recovery pending and exposes no
/// unconfirmed state. HTTP metadata is not authoritative for state contents.

pub async fn sync_public_endpoints(&self) -> Result<EndpointSyncReport> {
    let _identity_guard = self.claim_identity_operation("sync public endpoints")?;
    let (session_access, _, publication) = self
        .load_session_access_and_refresh_identity_with(|tx| {
            let lease = self.claim_paykit_app_operation_in_transaction(tx, false)?;
            crate::storage::require_paykit_app_active(tx, &self.config.app_id)?;
            Ok((lease, tx.public_endpoint_records()))
        })
        .await?;
    let session_access = session_access.ok_or_else(|| PaykitSdkError::Identity {
        context: "no Pubky session available".into(),
        source: None,
    })?;
    let (lease, records) = publication.expect("active session loads App publication state");
    let result = async {
        let details = self.payment.current_public_receiving_details().await?;
        self.sync_public_endpoints_with_lease(details, records, &lease, &session_access)
            .await
    }
    .await;
    self.finish_public_endpoint_sync(lease, result).await
}

/// SDK-derived Payment Request lifecycle state.
///
/// States are derived from the local durable stream and outbound queue. They do
/// not imply counterparty visibility unless the related outbound status is
/// [`OutboundPrivateMessageStatus::Sent`].
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[non_exhaustive]
pub enum PaymentRequestLifecycleState {
    /// Proposal is known locally and remains actionable.
    Proposed,
    /// Proposal is past its expiry.
    ProposalExpired,
    /// Acceptance is present locally.
    Accepted,
    /// Rejection is present locally.
    Rejected,
    /// Cancellation is present locally.
    Canceled,
    /// A one-time Payment Proof is present locally.
    ProofSubmitted,
    /// Recurring request acceptance is present locally.
    ActiveRecurring,
    /// A local outbound event may have advanced the private link without a durable checkpoint.
    RecoveryRequired,
    /// Event ordering, dedupe, or lifecycle validation found an invalid state.
    InvalidConflict,

pub async fn publish_paykit_app(
    &self,
    app: paykit_lib::PaykitApp,
) -> Result<paykit_lib::PaykitAppRegistry> {
    let _identity_guard = self.claim_identity_operation("publish Paykit app")?;
    let (session, _, noop_sequence) = self
        .load_session_access_and_refresh_identity_with(|tx| {
            Ok(app_publication_noop_lease_sequence(
                tx,
                &self.config.app_id,
                app.capabilities(),
                self.clock.now(),
            ))
        })
        .await?;
    let session = session.ok_or_else(|| PaykitSdkError::Identity {
        context: "publishing a Paykit app requires an active Pubky session".into(),
        source: None,
    })?;

pub async fn propose_payment_request(
    &self,
    counterparty: PubkyPublicKey,
    terms: PaymentRequestTerms,
) -> Result<PaymentRequestRecord> {
    let event = PaymentRequest::new(EventId::new_v4(), PaymentRequestId::new_v4(), terms);
    self.enqueue_raw_payment_request(counterparty, &event).await
}

/// Queue a Payment Request once using a caller-persisted Payment Request ID.
///
/// Persist the ID, counterparty, and exact original `terms` before calling.
/// Within this identity's shared SDK state, the ID is bound to the creating
/// App, counterparty, and exact canonical terms (including metadata, decimal
/// text, timestamps, and endpoint order). Reusing it with different valid input
/// returns [`PaykitSdkError::Policy`], even after expiry or a terminal state.
/// IDs already used by received proposals cannot create a local proposal.
///
/// A matching retry returns the current derived record with the original
/// proposal Event ID and outbound message ID, without enqueueing or resetting
/// delivery state. These IDs remain available if subsequent events invalidate
/// the lifecycle; they do not make the record actionable.
/// Lookup, insertion, and result derivation are atomic. Retry
/// with the same input after an uncertain commit or a caller restart. This
/// guarantee relies on retaining the identity's Event Message history; it
/// does not survive deleting that state or restoring a backup before creation.
///
/// Every call requires current session, identity, App capability, and link
/// checks. Session creation, capability scope, and key rotation remain the
/// caller's responsibility. The caller must establish counterparty support
/// for conversion and payment deadlines. Success describes the local queue,
/// not delivery, payment authorization, or counterparty processing.
pub async fn propose_payment_request_with_id(
    &self,
    counterparty: PubkyPublicKey,
    payment_request_id: PaymentRequestId,
    terms: PaymentRequestTerms,
) -> Result<PaymentRequestRecord> {
    self.with_storage_operation(Box::pin(async {
        let session = self.ensure_private_outbound_ready(&counterparty).await?;
        let identity = session.public_key()?;
        let request = PaymentRequest::new(EventId::new_v4(), payment_request_id, terms);
        self.storage
            .transaction(|tx| {
                crate::domain::payment_requests::enqueue_idempotent_payment_request(
                    tx,
                    &counterparty,
                    &self.config.app_id,
                    &request,
                    &identity,
                    self.clock.now(),
                )
            })
            .await
    }))
    .await

/// Resolve payable private endpoints for one counterparty.
///
/// This method only reads Private Payment Lists and only invokes the
/// private payment adapter callbacks. Public Payment Endpoints are never
/// considered as fallback candidates. Pass the last consumed
/// `private_payment_list_version` as `after_private_payment_list_version`
/// to require a newer list. When the current list is not newer, the result
/// is `WaitingForUpdatedPaymentList` and contains no payable endpoints.
///
/// Versions are opaque local freshness tokens scoped to this SDK state and
/// counterparty. The application owns
/// consumption policy and should persist a payable result's version before
/// submitting a payment that consumes the whole Private Payment List.
pub async fn resolve_private_contact_payment(
    &self,
    counterparty: PubkyPublicKey,
    amount: Option<PaymentAmountContext>,
    after_private_payment_list_version: Option<u64>,
) -> Result<PrivateContactPaymentResolution> {
    self.resolve_private_contact_payment_with_request(
        counterparty,
        amount,
        after_private_payment_list_version,
        None,
        None,
    )
    .await
}

/// Resolve private endpoints permitted by an actionable received Payment Request.
///
/// The request amount is passed to the payment adapter. Candidates are
/// restricted to the request's accepted Payment Endpoint Identifiers and,
/// when present, its required payee App before adapter selection.
/// Request-bound Payment Endpoints replace list discovery and have no list
/// version; `after_private_payment_list_version` does not apply to them.
pub async fn resolve_private_payment_request(
    &self,
    counterparty: PubkyPublicKey,
    payment_request_id: &PaymentRequestId,
    after_private_payment_list_version: Option<u64>,
) -> Result<PrivateContactPaymentResolution> {
    self.resolve_private_contact_payment_with_request(
        counterparty,
        None,
        after_private_payment_list_version,
        Some(payment_request_id),
        None,
    )
    .await
}

/// Resolve payable public Payment Endpoints for one counterparty.
///
/// This method only reads public Pubky storage and only invokes the public
/// payment adapter callbacks. Encrypted Link state is never consulted.
pub async fn resolve_public_contact_payment(
    &self,
