///
/// States are derived from the local durable stream and outbound queue. They do
/// not imply counterparty visibility unless the related outbound status is
/// [`OutboundPrivateMessageStatus::Sent`].
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[non_exhaustive]
pub enum PaymentRequestLifecycleState {
    /// Proposal is known locally and remains actionable.
    Proposed,
    /// Proposal is past its expiry.
    ProposalExpired,
    /// Acceptance is present locally.
    Accepted,
    /// Rejection is present locally.
    Rejected,
    /// Cancellation is present locally.
    Canceled,
    /// A one-time Payment Proof is present locally.
    ProofSubmitted,
    /// Recurring request acceptance is present locally.
    ActiveRecurring,
    /// A local outbound event may have advanced the private link without a durable checkpoint.
    RecoveryRequired,
    /// Event ordering, dedupe, or lifecycle validation found an invalid state.
    InvalidConflict,

PaymentRequestEvent::Acceptance(acceptance) => {
    if !payer_action_source_allowed(record, stored) {
        mark_invalid_stored(
            record,
            stored,
            "Payment Request acceptance came from the wrong side",
        );
        return;
    }
    if is_competing_payer_app(record, stored) {
        touch_stored_audit(record, stored);
        return;
    }
    if !has_terms(
        record,
        stored,
        "Payment Request acceptance arrived before proposal",
    ) {
        return;
    }
    if proposal_expired(record, stored.record_time()) {
        mark_invalid_stored(
            record,
            stored,
            "Payment Request acceptance arrived after proposal expiry",
        );
        return;
    }
    // Only the first Acceptance may cross a payee Cancellation; any
    // later Acceptance falls through to the transition check below.
    let crosses_payee_cancellation = record.state == PaymentRequestLifecycleState::Canceled
        && cancellation_was_sent_by_payee(record)
        && record.accepted_event_id.is_none()
        && record.rejected_event_id.is_none();
    if !matches!(record.state, PaymentRequestLifecycleState::Proposed)
        && !crosses_payee_cancellation
    {
        mark_invalid_stored(
            record,
            stored,
            "Payment Request acceptance arrived after transition",
        );
        return;
    }
    record.accepted_event_id = Some(acceptance.event_id().as_str().to_owned());
    record.accepted_outbound_status = outbound_status(stored);
    record.payer_app_id = stored.app_id();
    if !crosses_payee_cancellation {
        record.state = accepted_state(record);
    }
    touch_stored(record, stored);
}

    let records = payment_request_records(&storage, &counterparty, timestamp())
        .await
        .unwrap();

    assert_eq!(records[0].local_role, Some(PaymentRequestLocalRole::Payer));
    assert_eq!(records[0].state, PaymentRequestLifecycleState::Accepted);
    assert_eq!(
        records[0].accepted_event_id.as_deref(),
        Some("8a0d8b4c-913f-4e31-9f2c-2a6f5bb4d102")
    );
    assert_eq!(
        records[0].accepted_outbound_status,
        Some(OutboundPrivateMessageStatus::Pending)
    );
    assert_eq!(
        records[0].last_outbound_status,
        Some(OutboundPrivateMessageStatus::Pending)
    );
}

