#[derive(Clone, PartialEq, Eq, Hash)]
pub struct PaymentReference(String);

/// Maximum Payment Reference length in Unicode scalar values.
pub const PAYMENT_REFERENCE_MAX_LEN: usize = 256;

impl PaymentReference {
    /// Create a Payment Reference after validating that the input is non-empty,
    /// bounded, and free of control characters.
    pub fn new(reference: impl Into<String>) -> Result<Self> {
        let reference = reference.into();
        if reference.is_empty() {
            return Err(PaykitError::Validation(
                "Payment Reference must not be empty".into(),
            ));
        }
        let char_count = reference.chars().count();
        if char_count > PAYMENT_REFERENCE_MAX_LEN {
            return Err(PaykitError::Validation(format!(
                "Payment Reference must not exceed {PAYMENT_REFERENCE_MAX_LEN} characters, got {char_count}"
            )));
        }
        if let Some((pos, ch)) = reference.char_indices().find(|&(_, ch)| ch.is_control()) {
            return Err(PaykitError::Validation(format!(
                "Payment Reference must not contain control character U+{:04X} at byte {pos}",
                ch as u32
            )));
        }
        Ok(Self(reference))
    }

/// Payment Request terms set by the payee.
///
/// Fields cannot be mutated after validated construction.
///
/// ```compile_fail,E0616
/// fn cannot_mutate(mut value: paykit_lib::PaymentRequestTerms) {
///     value.accepted_payment_endpoint_identifiers = Vec::new();
/// }
/// ```
#[derive(Clone, PartialEq)]
pub struct PaymentRequestTerms {
    /// Requested amount.
    pub(super) amount: PaymentAmount,
    /// Payee-provided correlation value copied into Payment Proof messages.
    pub(super) payment_reference: PaymentReference,
    /// Proposal expiry before acceptance. `None` means no protocol-level
    /// proposal expiry.
    pub(super) proposal_expires_at: Option<String>,
    /// Optional recurrence. `None` means one-time request.
    pub(super) recurrence: Option<Recurrence>,
    /// Accepted Payment Endpoint Identifiers.
    pub(super) accepted_payment_endpoint_identifiers: Vec<PaymentEndpointIdentifier>,

/// Send a `paykit.payment_request` Event Message.
///
/// Payment Requests are payee-initiated; caller code must enforce the sender
/// role.
#[instrument(skip(link, event))]
pub async fn send_payment_request(
    link: &mut EncryptedLink,
    app_id: &PaykitAppId,
    event: &PaymentRequest,
) -> Result<()> {
    let json = serialize_payment_request_json(app_id, event)
        .map_err(|err| map_error("send_payment_request", err))?;
    link.send_payment_request_message(json.as_bytes())
        .await
        .map_err(|err| map_error("send_payment_request", err))
}

/// Send a `paykit.payment_request_acceptance` Event Message.
///
/// Acceptances are payer-initiated; caller code must enforce the sender role.
#[instrument(skip(link, event))]
pub async fn send_payment_request_acceptance(
    link: &mut EncryptedLink,
    app_id: &PaykitAppId,
    event: &PaymentRequestAcceptance,
) -> Result<()> {
    let json = serialize_acceptance_json(app_id, event)
        .map_err(|err| map_error("send_payment_request_acceptance", err))?;
    link.send_payment_request_acceptance_message(json.as_bytes())
        .await
        .map_err(|err| map_error("send_payment_request_acceptance", err))
}

impl PaymentRequest {
    pub(super) fn validate(&self) -> Result<()> {
        crate::validation::validate_outgoing_version_kind(
            self.version,
            self.kind,
            PrivateMessageKind::PaymentRequest,
            "Payment Request",
        )?;
        self.request.validate()
    }

    /// Construct a Payment Request proposal using protocol version 1.
    pub fn new(
        event_id: EventId,
        payment_request_id: PaymentRequestId,
        request: PaymentRequestTerms,
    ) -> Self {
        Self {
            version: 1,
            kind: PrivateMessageKind::PaymentRequest,
            event_id,
            payment_request_id,
            request,
        }
    }

/// UUID-v4 identifier for one Payment Request.
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub struct PaymentRequestId(String);

impl PaymentRequestId {
    /// Create a Payment Request ID from a UUID-v4 string.
    pub fn new(id: impl Into<String>) -> Result<Self> {
        validate_uuid_v4(id.into(), "Payment Request ID").map(Self)
    }

    /// Generate a fresh Payment Request ID.
    pub fn new_v4() -> Self {
        Self(uuid::Uuid::new_v4().to_string())
    }

    /// Access the canonical UUID string.
    pub fn as_str(&self) -> &str {
        &self.0
    }

impl PaymentRequestTerms {
    /// Start constructing terms with their required amount, reference, and endpoints.
    ///
    /// Call [`PaymentRequestTermsBuilder::build`] to validate the complete terms.
    pub fn builder(
        amount: PaymentAmount,
        payment_reference: PaymentReference,
        accepted_payment_endpoint_identifiers: Vec<PaymentEndpointIdentifier>,
    ) -> PaymentRequestTermsBuilder {
        PaymentRequestTermsBuilder(Self {
            amount,
            payment_reference,
            accepted_payment_endpoint_identifiers,
            payment_endpoints: None,
            required_app_id: None,
            proposal_expires_at: None,
            recurrence: None,
            conversion: None,
            payment_deadline: None,
            metadata: JsonMap::new(),
        })
    }
}

/// Validate the complete terms, including the non-empty endpoint list.
pub fn build(self) -> Result<PaymentRequestTerms> {
    self.0.validate()?;
    Ok(self.0)
}

impl PaymentRequestTermsBuilder {
    /// Bind payment to immutable Payment Endpoints owned by `required_app_id`.
    ///
    /// A supplied map must be nonempty, contain nonempty payloads, and use only
    /// accepted Payment Endpoint Identifiers. `required_app_id` must be set.
    /// `None` preserves endpoint discovery; `Some` forbids fallback outside the map.
    pub fn payment_endpoints(
        mut self,
        value: Option<HashMap<PaymentEndpointIdentifier, PaymentEndpointPayload>>,
    ) -> Self {
        self.0.payment_endpoints = value;
        self
    }
    /// Constrain payment to an endpoint owned by the specified payee App.
    pub fn required_app_id(mut self, value: Option<crate::PaykitAppId>) -> Self {
        self.0.required_app_id = value;
        self
    }

/// One Private Application Message received from an Encrypted Link.
///
/// This is the low-level receive item for the Private Application Message stream.
/// It keeps the raw plaintext payload so callers can route and persist messages
/// themselves. If decrypted bytes are not UTF-8, `raw_json` contains a local
/// invalid-JSON marker with the bytes encoded as base64url. Higher layers should
/// treat that marker as malformed input, not as a Private Application Message.
#[derive(Clone, PartialEq, Eq)]
pub struct PrivateApplicationMessage {
    /// Private Application Message version from the JSON `version` field, when
    /// the field is present and can be represented as a `u8`.
    pub version: Option<u8>,
    /// Message kind string from the JSON `kind` field, when the field is a
    /// string.
    pub kind: Option<String>,
    /// App ID string from the JSON `app_id` field, when the field is a string.
    pub app_id: Option<String>,
    /// Raw plaintext received over the Encrypted Link.
    pub raw_json: String,
}

impl std::fmt::Debug for PrivateApplicationMessage {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("PrivateApplicationMessage")
            .field("version", &self.version)
            .field("kind", &self.kind)
            .field("app_id", &self.app_id)
            .field(
                "raw_json",
                &format_args!("<redacted:{} bytes>", self.raw_json.len()),
            )
            .finish()

/// Versioned Private Payment List sent over an established Encrypted Link.
#[derive(Clone, PartialEq, Eq)]
pub struct PrivatePaymentList {
    version: u8,
    kind: PrivateMessageKind,
    app_id: PaykitAppId,
    /// Complete Payment List carried by this Latest-State Message.
    pub payment_endpoints: HashMap<PaymentEndpointIdentifier, PaymentEndpointPayload>,
}

impl fmt::Debug for PrivatePaymentList {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("PrivatePaymentList")
            .field("version", &self.version)
            .field("kind", &self.kind)
            .field("app_id", &self.app_id)
            .field(
                "payment_endpoints",
                &format_args!("<redacted:{} endpoints>", self.payment_endpoints.len()),
            )
            .finish()
    }
}

impl PrivatePaymentList {
    /// Construct a Private Payment List using protocol version 1 and the
    /// `paykit.private_payment_list` message kind.
    ///
    /// `payment_endpoints` is the complete list to share, not a patch.
    pub fn new(
        app_id: PaykitAppId,
        payment_endpoints: HashMap<PaymentEndpointIdentifier, PaymentEndpointPayload>,
    ) -> Self {
        Self {
            version: 1,
            kind: PrivateMessageKind::PrivatePaymentList,
            app_id,
            payment_endpoints,
        }
    }

/// Encrypts and sends a complete Private Payment List via the established
/// Encrypted Link.
///
/// The list must contain the full desired Payment List. Homeserver write
/// failures are retried according to [`EncryptedLink::set_max_send_retries`].
/// Oversized messages return [`crate::PaykitError::Validation`].
#[instrument(skip(link, list), fields(count = list.payment_endpoints.len()))]
pub async fn set_private_payment_list(
    link: &mut EncryptedLink,
    list: &PrivatePaymentList,
) -> Result<()> {
    debug!("sending Private Payment List");
    let json = serialize_private_payment_list_json(list)
        .map_err(|err| map_error("set_private_payment_list", err))?;
    link.send_private_payment_list_message(json.as_bytes())
        .await
        .map_err(|err| map_error("set_private_payment_list", err))
}

/// Resolve payable private endpoints for one counterparty.
///
/// This method only reads Private Payment Lists and only invokes the
/// private payment adapter callbacks. Public Payment Endpoints are never
/// considered as fallback candidates. Pass the last consumed
/// `private_payment_list_version` as `after_private_payment_list_version`
/// to require a newer list. When the current list is not newer, the result
/// is `WaitingForUpdatedPaymentList` and contains no payable endpoints.
///
/// Versions are opaque local freshness tokens scoped to this SDK state and
/// counterparty. The application owns
/// consumption policy and should persist a payable result's version before
/// submitting a payment that consumes the whole Private Payment List.
pub async fn resolve_private_contact_payment(
    &self,
    counterparty: PubkyPublicKey,
    amount: Option<PaymentAmountContext>,
    after_private_payment_list_version: Option<u64>,
) -> Result<PrivateContactPaymentResolution> {
    self.resolve_private_contact_payment_with_request(
        counterparty,
        amount,
        after_private_payment_list_version,
        None,
        None,
    )
    .await
}

PaymentRequestEvent::Proof(proof) => {
    if !payer_action_source_allowed(record, stored) {
        mark_invalid_stored(record, stored, "Payment Proof came from the wrong side");
        return;
    }
    let follows_cancellation = record.state == PaymentRequestLifecycleState::Canceled;
    if record.rejected_event_id.is_some() || !proof_follows_acceptance(record) {
        mark_invalid_stored(record, stored, "Payment Proof arrived before acceptance");
        return;
    }
    let Some(payer_app_id) = stored.app_id() else {
        mark_invalid_stored(record, stored, "Payment Proof has no payer App attribution");
        return;
    };
    let previous_proof = proof_for_billing_period(record, proof.billing_period().as_ref());
    if previous_proof.is_some_and(|existing| {
        events
            .get(existing.event_id.as_str())
            .and_then(|event| event.app_id())
            .as_ref()
            != Some(&payer_app_id)
    }) {
        touch_stored_audit(record, stored);
        return;
    }
    let correction = previous_proof.is_some();
    let Some(request) = request_from_record(record) else {
        mark_invalid_stored(
            record,
            stored,
            "Payment Proof cannot be correlated without proposal",
        );
        return;
    };
    let quote = proof
        .conversion_quote_id()
        .and_then(|id| events.get(id.as_str()))
        .and_then(|event| match event.event() {
            PaymentRequestEvent::ConversionQuote(quote) => Some(quote),
            _ => None,
        });
    if let Err(err) = proof.validate_conversion_quote(&request, quote) {
        mark_invalid_stored(record, stored, err.to_string());
        return;
    }
    record.payment_proofs.push(PaymentProofRecord {
        conversion_quote_id: proof.conversion_quote_id().map(|id| id.as_str().to_owned()),
        event_id: proof.event_id().as_str().to_owned(),
        outbound_message_id: match stored {
            StoredPaymentRequestEvent::Outbound { message, .. } => {
                Some(message.outbound_message_id)
            }
            StoredPaymentRequestEvent::Received { .. } => None,
        },
        outbound_status: outbound_status(stored),
        stream_item_id: match stored {
            StoredPaymentRequestEvent::Received { item, .. } => Some(item.stream_item_id),
            StoredPaymentRequestEvent::Outbound { .. } => None,
        },
        payment_reference: proof.payment_reference().as_str().to_owned(),
        billing_period: proof
            .billing_period()
            .as_ref()
            .map(BillingPeriodRecord::from),
        payment_endpoint_identifier: proof
            .payment_endpoint_identifier()
            .as_str()
            .to_owned(),
        payment_app_id: proof.payment_app_id().clone(),
        allowance_id: proof.allowance_id().map(|id| id.as_str().to_owned()),
        proof: proof.proof().clone(),
        recorded_at: stored.record_time(),
    });
    if !correction {
        record.payer_app_id = Some(payer_app_id);
    }
    record.state = if follows_cancellation {
        PaymentRequestLifecycleState::Canceled
    } else if request.request().recurrence().is_some() {
        PaymentRequestLifecycleState::ActiveRecurring
    } else {
        PaymentRequestLifecycleState::ProofSubmitted
    };
    touch_stored(record, stored);
}

    let records = payment_request_records(&storage, &counterparty, timestamp())
        .await
        .unwrap();

    assert_eq!(
        records[0].state,
        PaymentRequestLifecycleState::ProofSubmitted
    );
    assert_eq!(records[0].payment_proofs.len(), 1);
    assert_eq!(
        records[0].payment_proofs[0].outbound_status,
        Some(OutboundPrivateMessageStatus::Pending)
    );
    assert_eq!(
        records[0].last_outbound_status,
        Some(OutboundPrivateMessageStatus::Pending)
    );
    assert!(!format!("{:?}", records[0].payment_proofs[0]).contains("secret"));
}

/// Provides one application's live access to an identity-wide Paykit runtime.
///
/// The provider is the boundary where the app or bindings expose current Pubky
/// access from platform storage and auth flows.
#[async_trait]
pub trait PubkySessionProvider: Send + Sync {
    /// Load live Pubky access for storage and Encrypted Link workflows.
    ///
    /// Returning `None` means no live session access is currently available. It
    /// does not sign the SDK out or clear identity-scoped storage; explicit
    /// sign-out is a separate runtime operation.
    async fn load_session_access(&self) -> Result<Option<PubkySessionAccess>>;

/// Create encrypted Pubky-backed storage using the current live session.
///
/// The provider must supply identity-wide Paykit key material, either
/// directly or derived from the matching local Pubky identity secret, plus
/// a session with [`crate::PAYKIT_SESSION_CAPABILITIES`]. Session creation,
/// persistence, capability renewal, and key distribution remain the
/// caller's responsibility. Request timeouts come from the Pubky client.

/// Encrypted identity-wide SDK state stored in Pubky.
///
/// All serving homeserver instances must run 0.16.2 or newer with GCS storage.
/// Server versions and backends are not checked automatically; the caller must
/// verify deployment independently of the client version and `webdav-locks`.
/// All participating state writers must use lock tokens, and pre-upgrade writes
/// must be drained before rollout. Direct backend edits are outside this contract.
/// Each operation reads the latest complete state under a renewed homeserver
/// write lock. Its transactions reuse that state and replace the encrypted
/// resource whenever it changes, before returning. One instance serializes its
/// own operations. State is never reused after releasing the homeserver lock.
/// Encryption protects state contents and integrity, but not resource
/// existence, size, update timing, or replay by the homeserver. Unconfirmed
/// writes leave a remote marker. Before using that state, the next operation
/// republishes its exact bytes under the renewed lock. The confirmed publication
/// fences older GCS generations, including writes whose SQL transaction died.
/// Cancellation or failed publication leaves recovery pending and exposes no
/// unconfirmed state. HTTP metadata is not authoritative for state contents.

/// Authoritative logical state boundary for Paykit SDK.
///
/// Production adapters must provide atomic transactions with monotonic id
/// allocation, stable FIFO ordering for outbound/private-stream records, and
/// lease-aware writes. Apps sharing one Pubky identity must use the same
/// logical state backing. The SDK assumes all mutation methods called inside
/// one transaction either commit together or roll back together.
#[async_trait]
pub trait StorageAdapter: Send + Sync {
    /// Share storage access across the transactions of one bounded operation.
    ///
    /// Transactions still commit independently before returning. An operation
    /// error does not roll back earlier commits. Adapters may keep a write lock
    /// and its latest state for this future, so it must not wait on spawned tasks
    /// that access the same storage. Same-adapter nesting is supported on the
    /// same task. Do not call SDK methods from a storage operation: the SDK
    /// must acquire its session guard before entering shared storage. A write
    /// conflict must exit the operation before retrying with fresh state;
    /// earlier committed transactions are not replayed automatically.

// Event Message history is retained across delivery and terminal states.
// Compare canonical bytes, not typed equality or a normalized lifecycle view.
let state = tx.export_storage_state();
let mut proposal_ids = None;
for message in state.outbound_private_messages {
    if message.kind != PrivateMessageKind::PaymentRequest.as_str() {
        continue;
    }
    let parsed = parse_payment_request_event_message(&PrivateApplicationMessage {
        version: Some(1),
        kind: Some(message.kind),
        app_id: Some(message.app_id.to_string()),
        raw_json: message.raw_json,
    })
    .ok_or_else(|| PaykitSdkError::Protocol {
        context: "stored Payment Request proposal is unrecognized".into(),
        source: None,
    })?;
    if parsed.payment_request_id() != Some(request.payment_request_id()) {
        continue;
    }
    let Some(PaymentRequestEvent::Request(original)) = parsed.parsed_event() else {
        return Err(PaykitSdkError::Protocol {
            context: "stored Payment Request proposal is invalid".into(),
            source: None,
        });
    };
    if message.counterparty != *counterparty
        || message.app_id != *app_id
        || serialize_payment_request_event(
            app_id,
            &PaymentRequestEvent::Request(PaymentRequest::new(
                original.event_id().clone(),
                request.payment_request_id().clone(),
                request.request().clone(),
            )),
        )? != parsed.raw_json
    {
        return Err(PaykitSdkError::Policy {
            context: "Payment Request ID is already bound to a different proposal".into(),
            source: None,
        });
    }
    proposal_ids = Some((
        original.event_id().as_str().to_owned(),
        message.outbound_message_id,
    ));
}
let (event_id, outbound_message_id) = if let Some(ids) = proposal_ids {
    ids
} else {
